<?php
declare(strict_types=1);require __DIR__.'/app/bootstrap.php';
$type=$_GET['type']??'customer';$token=$_GET['token']??'';$error='';$ok=false;$q=db()->prepare("SELECT * FROM password_resets WHERE token_hash=? AND account_type=? AND used_at IS NULL AND expires_at>NOW() LIMIT 1");$q->execute([hash('sha256',(string)$token),$type]);$reset=$q->fetch();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$pass=(string)($_POST['password']??'');$confirm=(string)($_POST['confirm']??'');if(!$reset)$error='Link inválido ou expirado.';elseif(strlen($pass)<10||$pass!==$confirm)$error='As senhas devem ser iguais e ter pelo menos 10 caracteres.';else{$table=$type==='admin'?'admins':($type==='customer'?'customer_accounts':'reseller_accounts');if(!in_array($table,['admins','customer_accounts','reseller_accounts'],true))$error='Tipo de conta inválido.';else{$q=db()->prepare("UPDATE {$table} SET password_hash=? WHERE id=?");$q->execute([password_hash($pass,PASSWORD_DEFAULT),$reset['account_id']]);$q=db()->prepare('UPDATE password_resets SET used_at=NOW() WHERE id=?');$q->execute([$reset['id']]);$ok=true;}}}
layout_start('Nova senha');
?><section class="narrow"><h1>Crie uma nova senha</h1><?php if($ok):?><div class="notice">Senha atualizada. <a href="<?=$type==='admin'?'login.php':'customer-login.php'?>">Acesse sua conta.</a></div><?php else:?><?php if($error||!$reset):?><div class="notice error"><?=e($error?:'Link inválido ou expirado.')?></div><?php else:?><form method="post" class="panel"><?=client_csrf_field()?><label>Nova senha<input type="password" name="password" minlength="10" required></label><label>Confirme a senha<input type="password" name="confirm" minlength="10" required></label><button>Salvar nova senha</button></form><?php endif;?><?php endif;?></section><?php layout_end();?>